insert into public.questions (id, code, subject_id, topic_id, level, difficulty, board_id, year, qtype, theme, statement, explanation, hint, source, status, updated_at) values
  ('e1000000-0000-4000-a000-000000002711', 'EM-QUI-01375', 7, 201, 'medio', 4, 22, 2026, 'multiple_choice', 'Titulação', 'Na titulação de 25 mL de uma solução de HCl, gastaram-se 46 mL de NaOH a 0,5 mol/L até a neutralização completa. Qual é a concentração do ácido?', 'Mols de NaOH = 0,5 × 46/1000. A proporção HCl : NaOH é 1 : 1. C = 0,5·46/(1·25) = 0,92 mol/L.', 'No ponto de equivalência, mols de H⁺ = mols de OH⁻.', 'Questão autoral da Educa Mais no estilo da prova UNICAMP (2026). Não é uma questão oficial.', 'published', '2026-11-26T00:00:00.000Z'),
  ('e1000000-0000-4000-a000-000000002712', 'EM-QUI-01376', 7, 201, 'medio', 4, 23, 2026, 'multiple_choice', 'Titulação', 'Na titulação de 50 mL de uma solução de HCl, gastaram-se 18 mL de NaOH a 1 mol/L até a neutralização completa. Qual é a concentração do ácido?', 'Mols de NaOH = 1 × 18/1000. A proporção HCl : NaOH é 1 : 1. C = 1·18/(1·50) = 0,36 mol/L.', 'No ponto de equivalência, mols de H⁺ = mols de OH⁻.', 'Questão autoral da Educa Mais no estilo da prova ITA (2026). Não é uma questão oficial.', 'published', '2026-11-26T00:00:00.000Z'),
  ('e1000000-0000-4000-a000-000000002713', 'EM-QUI-01377', 7, 201, 'medio', 4, 23, 2026, 'multiple_choice', 'Titulação', 'Na titulação de 10 mL de uma solução de HCl, gastaram-se 21 mL de NaOH a 1 mol/L até a neutralização completa. Qual é a concentração do ácido?', 'Mols de NaOH = 1 × 21/1000. A proporção HCl : NaOH é 1 : 1. C = 1·21/(1·10) = 2,1 mol/L.', 'No ponto de equivalência, mols de H⁺ = mols de OH⁻.', 'Questão autoral da Educa Mais no estilo da prova ITA (2026). Não é uma questão oficial.', 'published', '2026-11-26T00:00:00.000Z'),
  ('e1000000-0000-4000-a000-000000002714', 'EM-QUI-01378', 7, 201, 'medio', 4, 20, 2026, 'multiple_choice', 'Titulação', 'Na titulação de 50 mL de uma solução de HCl, gastaram-se 17 mL de NaOH a 0,5 mol/L até a neutralização completa. Qual é a concentração do ácido?', 'Mols de NaOH = 0,5 × 17/1000. A proporção HCl : NaOH é 1 : 1. C = 0,5·17/(1·50) = 0,17 mol/L.', 'No ponto de equivalência, mols de H⁺ = mols de OH⁻.', 'Questão autoral da Educa Mais no estilo da prova ENEM (2026). Não é uma questão oficial.', 'published', '2026-11-26T00:00:00.000Z'),
  ('e1000000-0000-4000-a000-000000002715', 'EM-QUI-01379', 7, 201, 'medio', 4, 24, 2026, 'multiple_choice', 'Titulação', 'Na titulação de 50 mL de uma solução de HCl, gastaram-se 30 mL de NaOH a 1 mol/L até a neutralização completa. Qual é a concentração do ácido?', 'Mols de NaOH = 1 × 30/1000. A proporção HCl : NaOH é 1 : 1. C = 1·30/(1·50) = 0,6 mol/L.', 'No ponto de equivalência, mols de H⁺ = mols de OH⁻.', 'Questão autoral da Educa Mais no estilo da prova IME (2026). Não é uma questão oficial.', 'published', '2026-11-26T00:00:00.000Z'),
  ('e1000000-0000-4000-a000-000000002716', 'EM-QUI-01380', 7, 201, 'medio', 4, 21, 2026, 'multiple_choice', 'Titulação', 'Na titulação de 10 mL de uma solução de HCl, gastaram-se 31 mL de NaOH a 0,1 mol/L até a neutralização completa. Qual é a concentração do ácido?', 'Mols de NaOH = 0,1 × 31/1000. A proporção HCl : NaOH é 1 : 1. C = 0,1·31/(1·10) = 0,31 mol/L.', 'No ponto de equivalência, mols de H⁺ = mols de OH⁻.', 'Questão autoral da Educa Mais no estilo da prova FUVEST (2026). Não é uma questão oficial.', 'published', '2026-11-26T00:00:00.000Z'),
  ('e1000000-0000-4000-a000-000000002717', 'EM-QUI-01381', 7, 201, 'medio', 4, 24, 2026, 'multiple_choice', 'Titulação', 'Na titulação de 10 mL de uma solução de H₂SO₄, gastaram-se 50 mL de NaOH a 0,5 mol/L até a neutralização completa. Qual é a concentração do ácido?', 'Mols de NaOH = 0,5 × 50/1000. Cada H₂SO₄ neutraliza 2 NaOH, então mols de ácido = metade. C = 0,5·50/(2·10) = 1,25 mol/L.', 'No ponto de equivalência, mols de H⁺ = mols de OH⁻.', 'Questão autoral da Educa Mais no estilo da prova IME (2026). Não é uma questão oficial.', 'published', '2026-11-26T00:00:00.000Z'),
